package cn.zhuatech.agentsec.controller; import cn.zhuatech.agentsec.common.ApiResponse; import cn.zhuatech.agentsec.dto.AgentSecDto.*; import cn.zhuatech.agentsec.service.AgentSecService; import cn.zhuatech.agentsec.service.AgentAttackSimulationService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/shopfloor") @PreAuthorize("hasAnyRole('DOMAIN_USER','ADMIN')") public class WorkspaceController {private final AgentSecService service;private final AgentAttackSimulationService simulator;public WorkspaceController(AgentSecService service,AgentAttackSimulationService simulator){this.service=service;this.simulator=simulator;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.shopfloorDashboard());}@PostMapping("/work-orders/{id}/reports") public ApiResponse<ReportResult> report(@PathVariable Long id,@Valid @RequestBody ReportRequest request){return ApiResponse.ok("测试发现已提交",service.report(id,request));}@PostMapping("/attack-simulation") public ApiResponse<AgentAttackSimulationService.Result> simulate(@Valid @RequestBody AgentAttackSimulationService.Request request){return ApiResponse.ok("Agent 攻击演练完成",simulator.simulate(request));}}
